function UploadControl({ label, accept, onUploaded }: { label: string; accept: string; onUploaded: (path: string) => void }) {
  const uploadUrl = useRequestUploadUrl();
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  async function upload(file?: File) {
    if (!file) return;
    setBusy(true); setError('');
    try {
      const metadata = await uploadUrl.mutateAsync({ data: { name: file.name, size: file.size, contentType: file.type as 'image/jpeg' | 'image/png' | 'image/webp' | 'application/pdf' } });
      const response = await fetch(metadata.uploadURL, { method: 'PUT', headers: { 'Content-Type': file.type }, body: file });
      if (!response.ok) throw new Error('The file upload did not complete. Please try again.');
      onUploaded(metadata.objectPath);
    } catch (e) { setError(e instanceof Error ? e.message : 'Unable to upload this file.'); }
    finally { setBusy(false); }
  }
  return <div className="upload-wrap"><label className={`upload-control ${busy ? 'is-busy' : ''}`}><input type="file" accept={accept} disabled={busy} onChange={e => upload(e.target.files?.[0])} /><span className="upload-icon"><UploadCloud size={19} /></span><span><strong>{busy ? 'Uploading securely…' : label}</strong><small>{busy ? 'Direct encrypted transfer' : 'Choose a file · PNG, JPG, PDF · max 10 MB'}</small></span><ArrowRight className="upload-arrow" size={17} /></label>{error && <p className="form-error">{error}</p>}</div>;
}

