function AuthPage({ mode }: { mode: 'login' | 'register' | 'admin' }) {
  const [, setLocation] = useLocation();
  const client = useQueryClient();
  const login = useLoginMember(); const register = useRegisterMember(); const logout = useLogoutMember();
  const isAdminLogin = mode === 'admin';
  const [error, setError] = useState('');
  async function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); setError('');
    const form = new FormData(e.currentTarget);
    try {
      let isAdmin = false;
      if (mode === 'register') {
        const result = await register.mutateAsync({ data: { username: String(form.get('username')), email: String(form.get('email')), password: String(form.get('password')) } });
        isAdmin = Boolean(result.user?.isAdmin);
      } else {
        const result = await login.mutateAsync({ data: { identifier: String(form.get('identifier')), password: String(form.get('password')) } });
        isAdmin = Boolean(result.user?.isAdmin);
        if (!result.user || isAdmin !== isAdminLogin) {
          await logout.mutateAsync();
          await client.invalidateQueries({ queryKey: getGetSessionQueryKey() });
          setError(isAdminLogin ? 'This account does not have administrator access. Use member sign-in instead.' : 'This is an administrator account. Use the admin sign-in page.');
          return;
        }
      }
      await client.invalidateQueries({ queryKey: getGetSessionQueryKey() });
      setLocation(isAdmin ? '/admin' : '/dashboard');
    } catch (err) { setError(err instanceof Error ? err.message : 'We could not complete your request. Please try again.'); }
  }
  const pending = login.isPending || register.isPending;
  return <main className="auth-layout"><div className="auth-aside"><Link href="/" className="brand"><span className="brand-mark"><Coins size={20} /></span><span>TCK <b>TREASURY</b></span></Link><div className="auth-quote"><div className="eyebrow">{isAdminLogin ? 'TREASURY ADMINISTRATION' : 'A steady place for your money'}</div><h1>{isAdminLogin ? <>A secure space<br /><em>to manage.</em></> : <>Clarity in<br /><em>every balance.</em></>}</h1><p>{isAdminLogin ? 'Review member requests and manage treasury settings.' : 'NGN and TCK, held together in one considered account.'}</p></div><div className="auth-aside-footer"><ShieldCheck size={16} /> Your account is protected by secure sign-in.</div></div><section className="auth-main"><div className="auth-box"><div className="eyebrow">{isAdminLogin ? 'ADMIN SIGN IN' : mode === 'login' ? 'WELCOME BACK' : 'A CLEAR START'}</div><h2>{isAdminLogin ? 'Administrator sign in' : mode === 'login' ? 'Sign in to your account' : 'Open your account'}</h2><p className="muted">{isAdminLogin ? 'Use your administrator username or email and password.' : mode === 'login' ? 'Pick up right where you left off.' : 'A few details, then your treasury is ready.'}</p>{mode === 'register' && <Notice tone="info">The first account created on a new installation becomes the initial administrator.</Notice>}{error && <Notice tone="error">{error}</Notice>}<form onSubmit={submit} className="stack-form">{mode === 'register' ? <><Field name="username" label="Username" minLength={3} maxLength={32} required autoComplete="username" placeholder="Your display name" /><Field name="email" label="Email address" type="email" required autoComplete="email" placeholder="you@example.com" /><Field name="password" label="Password" type="password" minLength={10} required autoComplete="new-password" placeholder="At least 10 characters" /></> : <><Field name="identifier" label={isAdminLogin ? 'Admin username or email' : 'Username or email'} required autoComplete="username" placeholder={isAdminLogin ? 'Your admin username or email' : 'Your username or email'} /><Field name="password" label="Password" type="password" required autoComplete="current-password" placeholder="Your password" /></>}<Button type="submit" className="btn-full" disabled={pending}>{pending ? 'Please wait…' : mode === 'register' ? 'Create account' : isAdminLogin ? 'Sign in to admin' : 'Sign in securely'} <ArrowRight size={16} /></Button></form><div className="auth-switch">{mode === 'register' ? <>Already a member? <Link href="/login">Sign in</Link></> : isAdminLogin ? <>Member account? <Link href="/login">Member sign in</Link></> : <>New to TCK Treasury? <Link href="/register">Create an account</Link><br /><Link href="/admin/login">Administrator? Use admin sign-in</Link></>}</div><Link href="/" className="back-home"><ArrowRight size={14} /> Back to the overview</Link></div></section></main>;
}

